41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	};
50	
51	const quote = (step: QuoteStep): StepResult => {
52	  const policyBasePremium = step.items.reduce(
53	    (sum, item) => sum + BASE_PREMIUMS[item.type],
54	    0,
55	  );
56	  return {
57	    premium:
58	      policyBasePremium +
59	      policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE +
60	      PROCESSING_FEE,
61	  };
62	};
63	
64	const runStep = (step: Step): StepResult => {
65	  if (step.op === "quote") return quote(step);
66	  throw new Error(`Unsupported step: ${step.op}`);
67	};
68	
69	export const runScenario = (scenario: Scenario): ScenarioResult => ({
70	  results: scenario.steps.map(runStep),
71	});
